{
  "findings": [
    {
      "check_id": "CKV_AWS_45",
      "title": "IAM role allows * principal",
      "resource": "aws_iam_role.pass1",
      "severity": "CRITICAL",
      "explanation": "The assume_role_policy is referencing a data source that is not shown in this snippet, but if it contains a wildcard principal, it poses a significant risk as it allows any entity to assume this role."
    }
  ],
  "patched_code": "resource "aws_iam_role" "pass1" {
  name                = "pass1"
  assume_role_policy  = data.aws_iam_policy_document.instance_assume_role_policy.json
  managed_policy_arns = ["arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"]
}

data "aws_iam_policy_document" "instance_assume_role_policy" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}",
  "fix_summary": "Added a data block for aws_iam_policy_document.instance_assume_role_policy with a restricted principal to prevent wildcard assumptions."
}
